const names=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];const solfege=['do','do♯','re','re♯','mi','fa','fa♯','sol','sol♯','la','la♯','si'];function name(n){return names[n%12]+(Math.floor(n/12)-1)}function persist(){try{localStorage.setItem('piano-island',JSON.stringify({chapter,done:[...done]}));$('.save-status').textContent='● 学习进度自动保存'}catch{$('.save-status').textContent='进度仅在本次访问保存'}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
function drawNav(){let group='';$('#chapters').innerHTML=C.map((c,i)=>{let h='';if(c.group!==group){group=c.group;h=`<div class="nav-group">${group}</div>`}return h+`<button class="chapter ${i===chapter?'active':''}" data-chapter="${i}" ${i===chapter?'aria-current="step"':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span>${i===14?'示范曲与完整演奏':c.title}</span>${done.has(i)?'<span class="done">✓</span>':''}</button>`}).join('');$$('[data-chapter]').forEach(b=>b.onclick=()=>{selectChapter(+b.dataset.chapter);document.body.classList.remove('menu-open')});$('#courseProgress').style.width=done.size/15*100+'%';$('#progressText').textContent=`已完成 ${done.size} / 15 章`}
function selectChapter(i){stopPlayback();chapter=i;practiceIndex=0;quizOK=false;const c=C[i];drawNav();$('#breadcrumb').textContent=c.title;$('#chapterLabel').textContent=`CHAPTER ${String(i+1).padStart(2,'0')} · ${c.group}`;$('#title').textContent=c.hero;$('#subtitle').textContent=c.sub;$('#duration').textContent=`◷ 约 ${c.time} 分钟`;$('#lessonTitle').textContent=c.heading;$('#level').textContent=c.group;$('#lessonBody').innerHTML=`<p>${c.body}</p><ol>${c.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="concept"><b>KEY IDEA</b><span>${c.concept}</span></div>`;$('#tip').textContent=c.tip;$('#diagramTitle').textContent=c.diagram;renderDiagram(c);$('#practiceTitle').textContent=c.practice;$('#practiceDesc').textContent=c.task;$('#question').textContent=c.q;$('#quizFeedback').textContent='';$('#practiceFeedback').textContent='点击下方琴键开始，也可以使用电脑键盘。';renderTargets();$('#answers').innerHTML=c.a.map((x,j)=>`<button data-answer="${j}">${String.fromCharCode(65+j)}. ${x}</button>`).join('');$$('[data-answer]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.answer===c.correct;b.classList.add(ok?'correct':'wrong');$('#quizFeedback').textContent=ok?'✓ 正确！把这个知识点用在练习里吧。':'再想一想，可以回到知识讲解寻找线索。';if(ok)quizOK=true});$('#chapterCount').textContent=`${String(i+1).padStart(2,'0')} / 15`;$('#previous').disabled=i===0;$('#complete').textContent=i===14?'完成课程 ✓':'完成本章，继续学习 →';$('#midiLabel').hidden=i!==14;$('#finalNotice').hidden=i!==14;$('#midiStatus').textContent='';prepareEvents();setTab(tab);persist()}
function setTab(t){tab=t;$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===t);b.setAttribute('aria-selected',b.dataset.tab===t)});for(const n of ['learn','practice','score'])$('#'+n+'Panel').hidden=n!==t;if(t==='score')renderScore()}
$$('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('#previous').onclick=()=>selectChapter(Math.max(0,chapter-1));$('#complete').onclick=()=>{done.add(chapter);persist();if(chapter<14){selectChapter(chapter+1);window.scrollTo({top:0,behavior:'smooth'});toast('已保存本章进度，继续下一章')}else{drawNav();toast('15 章课程已走完，继续让音乐成为日常。')}};$('#menu').onclick=()=>document.body.classList.toggle('menu-open');$('#help').onclick=()=>$('#helpDialog').showModal();$('#closeHelp').onclick=()=>$('#helpDialog').close();$('#restartPractice').onclick=()=>{practiceIndex=0;renderTargets();$('#practiceFeedback').textContent='从第一颗音符重新开始。'};
function renderTargets(){const c=C[chapter];$('#targetNotes').innerHTML=c.target.map((n,i)=>`<span class="target-note ${i<practiceIndex?'hit':i===practiceIndex?'current':''}">${name(n)}</span>`).join('')}
function checkPractice(n){if(tab!=='practice'||practiceIndex>=C[chapter].target.length)return;const target=C[chapter].target;if(n===target[practiceIndex]){practiceIndex++;renderTargets();$('#practiceFeedback').textContent=practiceIndex===target.length?'✓ 本组音符全部正确！试着再弹一次，让每个音更均匀。':`很好！接下来弹 ${name(target[practiceIndex])}。`}else{$('#practiceFeedback').textContent=`你弹了 ${name(n)}，请找到 ${name(target[practiceIndex])}。`}}
function renderDiagram(c){$('#diagram').classList.remove('diagram-enter');void $('#diagram').offsetWidth;$('#diagram').classList.add('diagram-enter');let svg='';if(['staff','grand'].includes(c.mode)){svg=staffDiagram(c.mode==='grand')}else if(c.mode==='numbers'){svg=`<svg viewBox="0 0 350 110">${['1','2','3','4','5','6','7'].map((n,i)=>`<text x="${25+i*49}" y="33" text-anchor="middle" fill="#405e48" font-size="24" font-family="Georgia">${n}</text><text x="${25+i*49}" y="63" text-anchor="middle" fill="#a18b67" font-size="12">${['do','re','mi','fa','sol','la','si'][i]}</text><text x="${25+i*49}" y="92" text-anchor="middle" fill="#8b9980" font-size="12">${'CDEFGAB'[i]}</text>`).join('')}</svg>`}else if(c.mode==='rhythm'){svg=`<svg viewBox="0 0 350 110"><path d="M25 70H325" stroke="#e2e6da"/>${[0,1,2,3].map((n)=>`<circle cx="${52+n*80}" cy="42" r="${n===0?14:10}" fill="${n===0?'#b99168':'#adc0a1'}"/><text x="${52+n*80}" y="88" text-anchor="middle" fill="#8b9980" font-size="12">第 ${n+1} 拍</text>`).join('')}</svg>`}else if(['symbols','progression','final'].includes(c.mode)){let words=c.mode==='symbols'?['C','Am','G7','C/E']:c.mode==='final'?['聆听','分手','合手','表达']:['C','G','Am','F'];svg=`<svg viewBox="0 0 350 110">${words.map((n,i)=>`<rect x="${i*88+3}" y="20" width="78" height="63" rx="8" fill="${i===0?'#e9eee1':'#f6f7f0'}"/><text x="${i*88+42}" y="58" text-anchor="middle" fill="#52704e" font-size="${c.mode==='final'?15:23}" font-family="Georgia">${n}</text>`).join('')}</svg>`}else{let highlight=['chord'].includes(c.mode)?[0,2,4]:c.mode==='semitone'?[0,1]:[];svg=`<svg viewBox="0 0 350 110">${Array.from({length:8},(_,i)=>`<rect x="${11+i*41}" y="8" width="40" height="91" rx="3" fill="${highlight.includes(i)?'#e2c69e':'#fafaf3'}" stroke="#cdd5c3"/><text x="${31+i*41}" y="87" text-anchor="middle" fill="#8e9d7c" font-size="10">${'CDEFGABC'[i]}</text>${c.mode==='fingers'&&i<5?`<text x="${31+i*41}" y="66" text-anchor="middle" fill="#b5976d" font-size="14">${i+1}</text>`:''}`).join('')}${[0,1,3,4,5].map(i=>`<rect x="${40+i*41}" y="8" width="23" height="53" rx="2" fill="#3f5144"/>`).join('')}${c.mode==='scale'?'<text x="175" y="109" text-anchor="middle" fill="#9c8966" font-size="8">全 · 全 · 半 · 全 · 全 · 全 · 半</text>':''}</svg>`}$('#diagram').innerHTML=svg}
function staffDiagram(grand){return `<svg viewBox="0 0 350 120">${[0,1,2,3,4].map(i=>`<path d="M20 ${25+i*12}H330" stroke="#cbd2c0"/>`).join('')}<text x="23" y="65" font-size="52" font-family="serif" fill="#6d8060">𝄞</text>${[60,62,64,65,67,69,71,72].map((n,i)=>{let y=85-i*6;return `${n===60?`<path d="M${66+i*32} ${y}h23" stroke="#6d8060"/>`:''}<ellipse cx="${77+i*32}" cy="${y}" rx="6" ry="4" transform="rotate(-20 ${77+i*32} ${y})" fill="#6d8060"/><path d="M${83+i*32} ${y}v-26" stroke="#6d8060"/><text x="${77+i*32}" y="111" text-anchor="middle" font-size="8" fill="#a08d6f">${name(n)}</text>`}).join('')}${grand?'<text x="284" y="12" font-size="8" fill="#8c977e">中央 C 连接高低谱表</text>':''}</svg>`}
// Audio: a decaying, multi-partial piano-like voice, shared by all interactions.
let audio,master,compressor,voices=new Set(),held=new Map(),noteCounts=new Map(),sustained=new Set();function initAudio(){if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=+$('#volume').value/100*.35;compressor=audio.createDynamicsCompressor();compressor.threshold.value=-18;compressor.ratio.value=6;master.connect(compressor);compressor.connect(audio.destination)}if(audio.state==='suspended')audio.resume();return audio}
function voice(n,velocity=.7){const ac=initAudio(),t=ac.currentTime,f=440*2**((n-69)/12),env=ac.createGain();env.connect(master);env.gain.setValueAtTime(0,t);env.gain.linearRampToValueAtTime(.28*velocity,t+.008);env.gain.exponentialRampToValueAtTime(Math.max(.0001,.13*velocity),t+.18);env.gain.exponentialRampToValueAtTime(.0001,t+7);let os=[];[1,2,3,4,6].forEach((harm,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=f*harm*(1+(harm-1)*.0002);g.gain.value=[1,.38,.17,.08,.025][i];o.connect(g);g.connect(env);o.start(t);o.stop(t+8);os.push(o)});const v={n,env,os,released:false,release(force=false){if(this.released)return;if(!force&&$('#sustain').checked){sustained.add(this);return}this.released=true;sustained.delete(this);env.gain.cancelScheduledValues(ac.currentTime);env.gain.setTargetAtTime(.00001,ac.currentTime,.09);os.forEach(o=>{try{o.stop(ac.currentTime+.65)}catch{}});setTimeout(()=>{env.disconnect();voices.delete(this)},750)}};voices.add(v);setTimeout(()=>v.release(true),7500);return v}
function illuminate(n,on){const count=Math.max(0,(noteCounts.get(n)||0)+(on?1:-1));noteCounts.set(n,count);const b=$(`[data-midi="${n}"]`);if(b)b.classList.toggle('active',count>0);if(pianoKeys.has(n)){const k=pianoKeys.get(n);k.mesh.position.y=k.y-(count? .035:0);k.mesh.material=count?keyLit:(k.black?blackMat:whiteMat)}}
function noteOn(n,v=.75){const a=voice(n,v);illuminate(n,true);noteSpark(n);$('#noteReadout').textContent=`${name(n)} · ${solfege[n%12]} · ${Math.round(440*2**((n-69)/12))} Hz`;return a}
function noteSpark(n){const host=$('#scene');if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const el=document.createElement('span');el.className='note-spark';el.textContent=['♪','♫','♩'][n%3];el.style.left=(52+(n-60)*1.35)+'%';el.style.color=['#a4794f','#68865c','#c1966b'][n%3];host.appendChild(el);setTimeout(()=>el.remove(),1400)}
function noteOff(n,v,force=false){v.release(force);illuminate(n,false)}
$('#volume').oninput=()=>{if(master)master.gain.setTargetAtTime(+$('#volume').value/100*.35,audio.currentTime,.03)};$('#sustain').onchange=()=>{if(!$('#sustain').checked)for(const v of [...sustained])v.release(true)};
const keyMap={a:60,w:61,s:62,e:63,d:64,f:65,t:66,g:67,y:68,h:69,u:70,j:71,k:72};let whiteIndex=0;const whites=[];for(let n=21;n<=108;n++)if(![1,3,6,8,10].includes(n%12))whites.push(n);$('#keyboard').innerHTML=whites.map(n=>{const sh=Object.keys(keyMap).find(k=>keyMap[k]===n)||'';return `<button class="key white ${n===60?'central':''}" data-midi="${n}" aria-label="弹奏 ${name(n)}"><span class="shortcut">${sh.toUpperCase()}</span><span>${name(n)}</span></button>`}).join('');for(let n=21;n<=108;n++){if([1,3,6,8,10].includes(n%12)){const before=whites.filter(x=>x<n).length;$('#keyboard').insertAdjacentHTML('beforeend',`<button class="key black" data-midi="${n}" style="left:calc(5px + (100% - 10px) * ${before/whites.length} - (100% - 10px) * 0.6 / 104)" aria-label="弹奏 ${name(n)}"></button>`)}}
$$('[data-midi]').forEach(b=>{b.onclick=e=>{if(e.detail===0){const n=+b.dataset.midi,v=noteOn(n);checkPractice(n);setTimeout(()=>noteOff(n,v),350)}};b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);const n=+b.dataset.midi;if(held.has(e.pointerId))return;held.set(e.pointerId,{n,v:noteOn(n)});checkPractice(n)};b.onpointerup=b.onpointercancel=e=>{const h=held.get(e.pointerId);if(h){noteOff(h.n,h.v);held.delete(e.pointerId)}}});let typed=new Map();window.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#helpDialog').open)return;const n=keyMap[e.key.toLowerCase()];if(n!==undefined){e.preventDefault();typed.set(e.key.toLowerCase(),{n,v:noteOn(n)});checkPractice(n)}});window.addEventListener('keyup',e=>{const h=typed.get(e.key.toLowerCase());if(h){noteOff(h.n,h.v);typed.delete(e.key.toLowerCase())}});window.addEventListener('blur',()=>{for(const h of [...typed.values(),...held.values()])noteOff(h.n,h.v,true);typed.clear();held.clear();end3DNote()});
let metroTimer=null,metroBeat=0;function clickBeat(){const rhythm=$('#diagram');rhythm.classList.remove('beat-pulse');void rhythm.offsetWidth;rhythm.classList.add('beat-pulse');const ac=initAudio(),o=ac.createOscillator(),g=ac.createGain();o.frequency.value=metroBeat++%4===0?1300:850;g.gain.setValueAtTime(.13,ac.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+.045);o.connect(g);g.connect(master);o.start();o.stop(ac.currentTime+.06)}function metroSchedule(){clickBeat();metroTimer=setTimeout(metroSchedule,60000/+$('#tempo').value)}$('#metronome').onclick=()=>{if(metroTimer){clearTimeout(metroTimer);metroTimer=null;$('#metronome').textContent='♩ 节拍器';$('#metronome').setAttribute('aria-pressed','false')}else{metroBeat=0;metroSchedule();$('#metronome').textContent='♩ 节拍器 开';$('#metronome').setAttribute('aria-pressed','true')}};
