async function loadBuiltinMidi(){try{const response=await fetch('./assets/merry-christmas-mr-lawrence.mid');if(!response.ok)throw Error('MIDI 加载失败');builtin={...parseMidi(await response.arrayBuffer()),title:'圣诞快乐，劳伦斯先生 · 钢琴 MIDI'};if(chapter===14&&!imported){stopPlayback();prepareEvents();$('#midiStatus').textContent=`✓ 已加载内置 MIDI · ${builtin.events.length} 个音符，可直接开始演奏。`}}catch(error){$('#finalNotice').textContent='内置 MIDI 加载失败，请刷新重试或手动导入 MIDI。';console.error(error)}}
